"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["1927"],{9787(e,t,o){o.r(t),o.d(t,{metadata:()=>n,default:()=>d,frontMatter:()=>r,contentTitle:()=>i,toc:()=>l,assets:()=>m});var n=JSON.parse('{"id":"reference/inventory/howtos/importSystems","title":"How to import systems from Inventory?","description":"alms \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/reference/inventory/howtos/importSystems.md","sourceDirName":"reference/inventory/howtos","slug":"/reference/inventory/howtos/importSystems","permalink":"/personal-av-docs/docs/reference/inventory/howtos/importSystems","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/reference/inventory/howtos/importSystems.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"How to import systems from Inventory?","sidebar_label":"How to import systems from Inventory?","sidebar_position":99,"edition":"alms","source":"https://doc.airvantage.net/alms/reference/inventory/howtos/importSystems","format":"md"}}'),s=o(4848),a=o(8453);let r={title:"How to import systems from Inventory?",sidebar_label:"How to import systems from Inventory?",sidebar_position:99,edition:"alms",source:"https://doc.airvantage.net/alms/reference/inventory/howtos/importSystems",format:"md"},i,m={},l=[];function c(e){let t={a:"a",p:"p",strong:"strong",...(0,a.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsxs)(t.p,{children:[":::note Edition\n",(0,s.jsx)(t.strong,{children:"alms"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,s.jsx)(t.a,{href:"https://doc.airvantage.net/alms/reference/inventory/howtos/importSystems",children:"Original page"}),".\n:::"]}),"\n",(0,s.jsx)(t.p,{children:"How to import systems from Inventory?\nGo to\nInventory > Systems\nand click on\nImport\n.\nEnter a CSV file for bulk system import in\nAirvantage\n. Download template\nhere\n. For more information on how-to fill the csv file, please check below.\nClick on\nStart\n.\nImport CSV file format\nTo import systems, you need first to create a system that will serve as a template. The firmware and applications set on this\ntemplate system\nwill be reused to create further systems. The\ntemplate system\nis identified through a UID (Unique Identifier) which is available in\nInventory > Systems > Details\n:\nYou can format your bulk import file depending on your needs. The portal server uses the file header to interpret the different lines. Here are the fields that can be part of the CSV header with their meaning and use.\nThe file format is a .csv file (comma separated text file). Both comma \u2018,\u2019 and semi-colon \u2018;\u2019 are supported as separators.\nAll fields are\noptional\n. Empty columns will set\nnull\nto that field. When a gateway is to be created, at least one of\nSERIAL NUMBER, IMEI\nmust be specified. When a subscription is to be created, at least one of\nIDENTIFIER, NETWORK IDENTIFIER\nmust be specified.\nFIELD\nDESCRIPTION\nNAME\nName to be set to the system\nTEMPLATE\nuid of the template system. Is mandatory if you create a system with a firmware or application.\nLABELS\nOne or more label(s) to be applied on the created system. For provinding several labels, use the pipe \u2018|\u2019 separator.\nGATEWAY[IMEI]\nIMEI of the Gateway to be assigned to the new system. If the gateway does not exist a new one will be created.\nGATEWAY[SERIAL NUMBER]\nSerial Number of the be assigned to the new system. If the gateway does not exists a new one will be created. Can be retreived or scanned from the Gateway or module.\nGATEWAY[MAC ADDRESS]\nMAC address of the gateway to be created.\nGATEWAY[TYPE]\nType of the gateway to be created. Can be values such as GX400, ES440 or FXT009 for AirLink gateways/modems or SL8080T, HL8548 for AirPrime modules.\nGATEWAY[LABELS]\nOne or more label(s) to be applied on the created gateway. For provinding several labels, use the pipe \u2018|\u2019 separator.\nGATEWAY_REF[UID]\nIn case you want to reuse a pre-created gateway, you may use its unique identifier UID.\nSUBSCRIPTION[IDENTIFIER]\nICCID/ESN of the subscription to be assigned to the new system. If the subscription does not exist a new one is created.\nSUBSCRIPTION[MOBILE NUMBER]\nMSISDN (telephone number) of the subscription to be created.\nSUBSCRIPTION[NETWORK IDENTIFIER]\nIMSI of the subscription to be created.\nSUBSCRIPTION[IP]\nIP address of the subscription to be created.\nSUBSCRIPTION[OPERATOR]\nSubscription operator. This field is mandatory for creating a system with a subscription.\nSUBSCRIPTION[OPERATOR ACCOUNT]\nuid of the operator account for the subscription to be created. This is required to use subscription management functionalities.\nSUBSCRIPTION[LABELS]\nOne or more label(s) to be applied on the created subscription. For provinding several labels, use the pipe \u2018|\u2019 separator.\nSUBSCRIPTION_REF[UID]\nIn case you want to reuse a pre-created subscription, you may use its unique identifier UID.\nMSCI[host]\nTo be used for AirLink gateways, as they use MSCI as a communication protocol. To be filled in for the server initiated option. If you are currently able to initiate communications out to the gateway either by public static IP or domain name, enter public IP address or complete domain name.\nMQTT[password]\nIf you use MQTT as a communication protocol, you will want to provide the MQTT password.\nMSCI[password]\nTo be used for AirLink gateways, as they use MSCI as a communication protocol. To be filled in for the server initiated option and to be able to remotely change the AceManager password. If you are currently able to initiate communications out to the gateway either by public static IP or domain name, enter the AceManager password used to login to this device directly.\nM3DA[password]\nIf you use M3DA as a communication protocol, you will want to provide the M3DA password. This is especially the case for ALEOS AF and AirPrime MC series.\nREST[password]\nIf you use REST as a communication protocol, you will want to provide the REST password.\nImport CSV file examples\nThe following examples show you how to format headers depending on whether gateways and subscriptions are already created in the\nAirVantage\n.\nCreating systems with a gateway referenced by its serial number\nNAME,TEMPLATE,GATEWAY[SERIAL NUMBER]\nMySystem,5221e1c2b2e54782aa0fe8e928c257c8,CA123456789045324\nCreating systems with a gateway referenced by its uid, a subscription, and system labels\nNAME,TEMPLATE,GATEWAY_REF[UID],LABELS,SUBSCRIPTION_REF[IDENTIFIER]\nMySystem,5221e1c2b2e54782aa0fe8e928c257c8,2e8b9db6678a4498bde1f9d85f0f7af4,NewYork|Demo,60DC26A7\nCreating systems with a new gateway, server initiated capabilites and labels for gateway and system\nNAME,TEMPLATE,GATEWAY[IMEI],GATEWAY[MAC ADDRESS],GATEWAY[SERIAL NUMBER],GATEWAY[TYPE],GATEWAY[LABELS],LABELS,MSCI[HOST],MSCI[PASSWORD]\nMySystem,5221e1c2b2e54782aa0fe8e928c257c8,123456789074689,01:23:45:67:89:AB,SW31MBP0064162,ES440,Shipped,NewYork|Demo,343.76.2.45,12345\nCreating systems with a new gateway and a new KPN subscription\nNAME,TEMPLATE,GATEWAY[SERIAL NUMBER],GATEWAY[TYPE],SUBSCRIPTION[IDENTIFIER], SUBSCRIPTION[OPERATOR]\nMySystem,5221e1c2b2e54782aa0fe8e928c257c8,SW31MBP0064162,ES440,8912345678907543247,KPN"})]})}function d(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(c,{...e})}):c(e)}},8453(e,t,o){o.d(t,{R:()=>r,x:()=>i});var n=o(6540);let s={},a=n.createContext(s);function r(e){let t=n.useContext(a);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:r(e.components),n.createElement(a.Provider,{value:t},e.children)}}}]);